<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x65B9;&#x7A0B;&#x6C42;&#x89E3;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="type-row"><view class="type-btn" :class="{active: eqType==='linear'}" @click="eqType='linear'">ax+b=0</view><view class="type-btn" :class="{active: eqType==='quad'}" @click="eqType='quad'">ax\u00B2+bx+c=0</view><view class="type-btn" :class="{active: eqType==='system'}" @click="eqType='system'">&#u4E92;&#u5143;&#u65B9;&#u7A0B;</view></view><view v-if="eqType==='linear'" class="input-section"><view class="coef-row"><text class="coef-label">a:</text><input class="coef-input" type="number" v-model.number="la" /></view><view class="coef-row"><text class="coef-label">b:</text><input class="coef-input" type="number" v-model.number="lb" /></view><view class="solve-btn" @click="solveLinear"><text>&#x6C42;&#x89E3;</text></view><view v-if="linearResult" class="result-box"><text class="result-text">{{linearResult}}</text></view></view><view v-if="eqType==='quad'" class="input-section"><view class="coef-row"><text class="coef-label">a:</text><input class="coef-input" type="number" v-model.number="qa" /></view><view class="coef-row"><text class="coef-label">b:</text><input class="coef-input" type="number" v-model.number="qb" /></view><view class="coef-row"><text class="coef-label">c:</text><input class="coef-input" type="number" v-model.number="qc" /></view><view class="solve-btn" @click="solveQuad"><text>&#x6C42;&#x89E3;</text></view><view v-if="quadResult" class="result-box"><text class="result-text">{{quadResult}}</text></view></view><view v-if="eqType==='system'" class="input-section"><text class="hint-text">&#x65B9;&#x7A0B; 1: ax + by = c</text><view class="coef-row"><text class="coef-label">a:</text><input class="coef-input" type="number" v-model.number="s1a" /><text class="coef-label">b:</text><input class="coef-input" type="number" v-model.number="s1b" /><text class="coef-label">c:</text><input class="coef-input" type="number" v-model.number="s1c" /></view><text class="hint-text">&#x65B9;&#x7A0B; 2: ax + by = c</text><view class="coef-row"><text class="coef-label">a:</text><input class="coef-input" type="number" v-model.number="s2a" /><text class="coef-label">b:</text><input class="coef-input" type="number" v-model.number="s2b" /><text class="coef-label">c:</text><input class="coef-input" type="number" v-model.number="s2c" /></view><view class="solve-btn" @click="solveSystem"><text>&#x6C42;&#x89E3;</text></view><view v-if="systemResult" class="result-box"><text class="result-text">{{systemResult}}</text></view></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const eqType = ref("linear")
const la = ref(1); const lb = ref(0)
const qa = ref(1); const qb = ref(0); const qc = ref(0)
const s1a = ref(1); const s1b = ref(1); const s1c = ref(0)
const s2a = ref(1); const s2b = ref(-1); const s2c = ref(0)
const linearResult = ref("")
const quadResult = ref("")
const systemResult = ref("")
function goBack() { uni.navigateBack() }
function solveLinear() { if (la.value === 0) { linearResult.value = lb.value === 0 ? "无穷多解" : "无解"; return } linearResult.value = "x = " + (-lb.value / la.value).toFixed(4) }
function solveQuad() { if (qa.value === 0) { linearResult.value = "不是二次方程"; return } var d = qb.value*qb.value - 4*qa.value*qc.value; if (d > 0) { var x1 = (-qb.value + Math.sqrt(d)) / (2*qa.value); var x2 = (-qb.value - Math.sqrt(d)) / (2*qa.value); quadResult.value = "判别式 = " + d.toFixed(2) + "\nx1 = " + x1.toFixed(4) + "\nx2 = " + x2.toFixed(4) } else if (d === 0) { quadResult.value = "判别式 = 0\nx = " + (-qb.value / (2*qa.value)).toFixed(4) } else { quadResult.value = "判别式 = " + d.toFixed(2) + "\n无实数根" } }
function solveSystem() { var det = s1a.value*s2b.value - s1b.value*s2a.value; if (det === 0) { systemResult.value = "无解或无穷多解"; return } var x = (s1c.value*s2b.value - s1b.value*s2c.value) / det; var y = (s1a.value*s2c.value - s1c.value*s2a.value) / det; systemResult.value = "x = " + x.toFixed(4) + "\ny = " + y.toFixed(4) }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#0891b2,#0e7490);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.type-row{display:flex;gap:8rpx;margin-bottom:24rpx}.type-btn{flex:1;padding:16rpx 8rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:22rpx;color:#666}.type-btn.active{background:linear-gradient(135deg,#0891b2,#0e7490);color:#fff}.input-section{background:#fff;border-radius:16rpx;padding:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.coef-row{display:flex;align-items:center;margin-bottom:16rpx;gap:8rpx}.coef-label{font-size:26rpx;color:#666;width:40rpx}.coef-input{flex:1;height:72rpx;background:#f5f7fb;border-radius:8rpx;padding:0 16rpx;font-size:28rpx;border:2rpx solid #eee}.hint-text{font-size:24rpx;color:#999;display:block;margin:12rpx 0}.solve-btn{background:linear-gradient(135deg,#0891b2,#0e7490);border-radius:16rpx;padding:24rpx;text-align:center;margin-top:24rpx}.solve-btn text{font-size:30rpx;color:#fff;font-weight:600}.result-box{background:#eef2ff;border-radius:12rpx;padding:24rpx;margin-top:24rpx}.result-text{font-size:28rpx;color:#0e7490;font-weight:600;white-space:pre-line;line-height:1.6}</style>